<?php
namespace Modules\Ran\Services;
use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Facades\Mail;use Modules\Ran\Entities\CommunicationLog;use Modules\Ran\Support\RanContext;use Throwable;
class CommunicationService{public function __construct(private DocumentService $documents){}
 public function send(string $type,Model $document,string $channel,string $recipient,array $sections,?string $message=null):CommunicationLog{$share=$this->documents->share($type,(int)$document->id,$channel,$sections);$url=$this->documents->publicUrl($share);$title=$this->documents->title($type,$document);$body=trim(($message?:$title)."\n".$url);$log=CommunicationLog::create(['business_id'=>RanContext::businessId(),'location_id'=>$document->location_id??RanContext::locationId(),'store_id'=>$document->store_id??RanContext::storeId(),'channel'=>$channel,'document_type'=>$type,'document_id'=>$document->id,'recipient'=>$recipient,'subject'=>$title,'message'=>$body,'share_url'=>$url,'status'=>'queued']);try{$result=$this->deliver($channel,$recipient,$title,$body);$success=(bool)($result['success']??false);$log->update(['status'=>$success?'sent':'failed','provider_reference'=>$result['provider_reference']??null,'provider_response'=>json_encode($result,JSON_UNESCAPED_UNICODE),'sent_at'=>$success?now():null,'failed_at'=>$success?null:now(),'failure_reason'=>$success?null:($result['response_message']??'Provider rejected message')]);}catch(Throwable $e){$log->update(['status'=>'failed','failed_at'=>now(),'failure_reason'=>$e->getMessage()]);}return $log->refresh();}
 private function deliver(string $channel,string $recipient,string $subject,string $body):array{$manager='Modules\\CommunicationHub\\Services\\Providers\\ChannelProviderManager';if(class_exists($manager))return app($manager)->send($channel,['business_id'=>RanContext::businessId(),'to'=>$recipient,'recipient'=>$recipient,'subject'=>$subject,'body'=>$body,'message'=>$body,'source'=>'ran']);if($channel==='email'){Mail::raw($body,fn($mail)=>$mail->to($recipient)->subject($subject));return ['success'=>true,'provider_reference'=>'LARAVEL-MAIL-'.now()->format('YmdHis')];}return ['success'=>false,'response_message'=>'Communication Hub is unavailable. Configure it before sending SMS or WhatsApp.'];}
}
